      hu: ["A lakosság 2 000 fő.", "A terület 1 km².", "Az első házak 1978-ban épültek.", "Az iskola 1982-ben nyílt meg.", "A legmagasabb pont 50 m.", "A buszjáratok száma napi 30."],
      ro: ["Populația: 2.000.", "Suprafața: 1 km².", "Anul dezvoltării: 1975.", "Distanța până la Bridgetown: 5 km.", "Altitudinea medie: 40 m.", "Numărul de case: 500."],
      en: ["Population: 2,000.", "Area: 1 km².", "Elevation: 40 m above sea level.", "Distance from Bridgetown: 5 km.", "Year of development: 1975.", "Number of houses: 500."],
      pt: ["A população é de cerca de 2.000 habitantes.", "A distância até Bridgetown é de 5 km.", "O loteamento começou em 1975.", "A altitude média é de 40 m.", "Existe uma escola primária.", "A área da zona residencial é de 1 km²."],
